# Surah Yunus (chapter 10) — part 5: ayat 41-50 (IDs 1405-1414)
SURAH = 10

ENTRIES = {
1405: (
"اور — اگر — وہ — آپؐ کو — جھٹلائیں — تو کہدو — میرا عمل — میرے لیے — اور — تمہارا عمل — تمہارے لیے — تم — برئی الذمہ — ہو — اس — سے جو — میں عمل کرتا ہوں — اور — میں — برئی الذمہ — ہوں — اس — سے جو — تم عمل کرتے ہو",
"""۱۔ کفار جھٹلائیں — تو — اپنا عمل — انہیں ذمہ دار بناؤ۔
۲۔ ’’وَإِن كَذَّبُوكَ فَقُلْ لِّي عَمَلِي وَلَكُمْ عَمَلُكُمْ أَنتُم بَرِيئُونَ مِمَّا أَعْمَلُ وَأَنَا بَرِيءٌ مِّمَّا تَعْمَلُونَ‘‘ — اور — اگر — وہ — آپؐ کو — جھٹلائیں — تو کہدو — میرا عمل — میرے لیے — اور — تمہارا عمل — تمہارے لیے — تم — برئی الذمہ — ہو — اس — سے جو — میں عمل کرتا ہوں — اور — میں — برئی الذمہ — ہوں — اس — سے جو — تم عمل کرتے ہو — یعنی اگر وہ آپؐ کو جھٹلائیں — آپؐ کہہ دیں — مجھے اپنے عمل کی فکر ہے — اور تمہارے عمل — کی ذمہ داری تمہاری ہے۔
۳۔ عملی سبق: اپنے عمل — پر نظر رکھیں؛ دوسروں کے اعمال — ان کی ذمہ داری ہیں۔"""
),
1406: (
"اور — ان — میں — کچھ — ایسے ہیں — جو — آپؐ کی بات سنتے ہیں — کیا — آپؐ — بہرے — کو — سنا سکتے ہیں — خواہ — وہ — نہ — سمجھتے ہوں",
"""۱۔ سننا — اور سمجھنا — دو مختلف — باتیں ہیں۔
۲۔ ’’وَمِنْهُم مَّن يَسْتَمِعُونَ إِلَيْكَ أَفَأَنتَ تُسْمِعُ الصُّمَّ وَلَوْ كَانُوا لَا يَعْقِلُونَ‘‘ — اور — ان — میں — کچھ — ایسے ہیں — جو — آپؐ کی بات سنتے ہیں — کیا — آپؐ — بہرے — کو — سنا سکتے ہیں — خواہ — وہ — نہ — سمجھتے ہوں — یعنی وہ سنتے ہیں مگر نہیں سمجھتے؛ بہرہ — وہ — ہے جو سمجھتا نہیں۔
۳۔ عملی سبق: سننا — سمجھنا بنے — تو — فائدہ ہے۔"""
),
1407: (
"اور — ان — میں — کچھ — ایسے ہیں — جو — آپؐ کی طرف — دیکھتے ہیں — کیا — آپؐ — اندھوں — کو — ہدایت دے سکتے ہیں — خواہ — وہ — نہ — دیکھتے ہوں",
"""۱۔ دیکھنا — سمجھنا — دو — مختلف — باتیں ہیں۔
۲۔ ’’وَمِنْهُم مَّن يَنظُرُ إِلَيْكَ أَفَأَنتَ تَهْدِي الْعُمْيَ وَلَوْ كَانُوا لَا يُبْصِرُونَ‘‘ — اور — ان — میں — کچھ — ایسے ہیں — جو — آپؐ کی طرف — دیکھتے ہیں — کیا — آپؐ — اندھوں — کو — ہدایت دے سکتے ہیں — خواہ — وہ — نہ — دیکھتے ہوں — یعنی وہ دیکھتے ہیں مگر — آنکھوں کے باوجود بصیرت — نہیں؛ ہدایت — اللہ — دیتا ہے۔
۳۔ عملی سبق: ہدایت — صرف اللہ — کی طرف سے ہے؛ آنکھوں کا — دیکھنا — کافی نہیں۔"""
),
1408: (
"بے شک — اللہ — لوگوں پر — کچھ بھی ظلم — نہیں کرتا — لیکن — لوگ — خود اپنے آپ — پر ظلم کرتے ہیں",
"""۱۔ اللہ کبھی ظلم — نہیں کرتا؛ انسان خود — ناحق کا — شکار ہوتا ہے۔
۲۔ ’’إِنَّ اللَّهَ لَا يَظْلِمُ النَّاسَ شَيْئًا وَلَٰكِنَّ النَّاسَ أَنفُسَهُمْ يَظْلِمُونَ‘‘ — بے شک — اللہ — لوگوں پر — کچھ بھی ظلم — نہیں کرتا — لیکن — لوگ — خود اپنے آپ — پر ظلم کرتے ہیں — یعنی اللہ — کبھی کسی — پر ظلم نہیں کرتا — انسان — خود اپنی جانوں پر ظلم — کرتے ہیں۔
۳۔ عملی سبق: گناہ — اپنی جان کو — نقصان ہے؛ اللہ — مہربان ہے۔"""
),
1409: (
"اور — جس — دن — وہ — ان — سب کو — جمع کرے گا — گویا — انہوں نے — صرف ایک — دن کے — ایک — گھڑی — تک — ٹھہرے ہوں — ایک دوسرے سے — پہچان — کریں گے — یقیناً — وہ — لوگ جنہوں نے — اللہ سے ملاقات — کو جھٹلایا — نقصان — میں — پڑے — اور — وہ — ہدایت — یافتہ نہیں تھے",
"""۱۔ قیامت — جلد آئے گی؛ دنیا کی عمر مختصر لگے گی۔
۲۔ ’’وَيَوْمَ يَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُوا إِلَّا سَاعَۃً مِّنَ النَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْ قَدْ خَسِرَ الَّذِينَ كَذَّبُوا بِلِقَاءِ اللَّهِ وَمَا كَانُوا مُهْتَدِينَ‘‘ — اور — جس — دن — وہ — ان — سب کو — جمع کرے گا — گویا — انہوں نے — صرف ایک — دن کے — ایک — گھڑی — تک — ٹھہرے ہوں — ایک دوسرے سے — پہچان — کریں گے — یقیناً — وہ — لوگ جنہوں نے — اللہ سے ملاقات — کو جھٹلایا — نقصان — میں — پڑے — اور — وہ — ہدایت — یافتہ نہیں تھے — یعنی قیامت — بہت جلد آئے گی — دنیا میں ٹھہرنے کا وقت — مختصر لگے گا؛ ملاقات کو جھٹلانے والے — خسارہ — میں پڑے۔
۳۔ عملی سبق: ملاقات — اللہ کی — ہوگی — تیاری — کرو۔"""
),
1410: (
"اور — اگر — ہم — آپؐ کو — ان — چیزوں — کا — کچھ — دکھا دیں — جن — کا — ہم — ان — سے وعدہ کر رہے ہیں — یا — آپؐ کی موت — اس — سے پہلے — ہو جائے — تو بھی — ہماری طرف — ان — کا لوٹ — آنا ہے — پھر — اللہ — ان — کے — اعمال — پر — گواہ ہے",
"""۱۔ عذاب — اگر آپؐ — کی زندگی میں نہ آئے تو — بھی — آئے گا۔
۲۔ ’’وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُمَّ اللَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَلُونَ‘‘ — اور — اگر — ہم — آپؐ کو — ان — چیزوں — کا — کچھ — دکھا دیں — جن — کا — ہم — ان — سے وعدہ کر رہے ہیں — یا — آپؐ کی موت — اس — سے پہلے — ہو جائے — تو بھی — ہماری طرف — ان — کا لوٹ — آنا ہے — پھر — اللہ — ان — کے — اعمال — پر — گواہ ہے — یعنی ان کا — عذاب — آنا ہے — چاہے زندگی میں یا موت کے بعد؛ اللہ — ان کے اعمال — پر گواہ ہے۔
۳۔ عملی سبق: اللہ — ہر چیز پر — گواہ ہے؛ چھپ کر گناہ — متکرو۔"""
),
1411: (
"اور — ہر امت — کا — ایک رسول — ہے — پس — جب — ان — کا رسول — آ جائے گا — تو — ان — کے درمیان — انصاف کے ساتھ — فیصلہ کر دیا جائے گا — اور — ان — پر ظلم — نہیں ہوگا",
"""۱۔ ہر امت — کو — رسول — بھیجا گیا۔
۲۔ ’’وَلِكُلِّ أُمَّۃٍ رَّسُولٌ فَإِذَا جَاءَ رَسُولُهُمْ قُضِيَ بَيْنَهُم بِالْقِسْطِ وَهُمْ لَا يُظْلَمُونَ‘‘ — اور — ہر امت — کا — ایک رسول — ہے — پس — جب — ان — کا رسول — آ جائے گا — تو — ان — کے درمیان — انصاف کے ساتھ — فیصلہ کر دیا جائے گا — اور — ان — پر ظلم — نہیں ہوگا — یعنی ہر امت — کا — ایک رسول ہے — قیامت میں — انصاف کے ساتھ — فیصلہ ہو گا؛ کوئی ظلم نہیں ہوگا۔
۳۔ عملی سبق: ہر — امت کو حق کا — علم ملا؛ اللہ — انصاف — کرے گا۔"""
),
1412: (
"وہ — کہتے ہیں — یہ وعدہ — کب — پورا ہو گا — اگر — تم سچے ہو",
"""۱۔ کفار — عذاب کا — وقت — پوچھتے ہیں۔
۲۔ ’’وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَادِقِينَ‘‘ — وہ — کہتے ہیں — یہ وعدہ — کب — پورا ہو گا — اگر — تم سچے ہو — یعنی کافر — پوچھتے ہیں — یہ وعدہ — کب — پورا ہوگا — اگر تم سچے ہو۔
۳۔ عملی سبق: عذاب — کا وقت — اللہ جانتا ہے؛ انسان کو — انتظار کرنا ہے۔"""
),
1413: (
"کہدو — میں — اپنے لیے — نقصان — اور — فائدہ — دونوں کا — اختیار نہیں رکھتا — مگر — جتنا — اللہ — چاہے — ہر امت — کا — ایک وقت معین — ہے — جب — ان کا وقت — آ جاتا ہے — تو — نہ — ایک گھڑی — تاخیر ہوتی ہے — نہ — تقدیم ہوتی ہے",
"""۱۔ نبیؐ — بھی — صرف — اللہ کے اذن سے — کچھ کر سکتے ہیں۔
۲۔ ’’قُلْ لَّا أَمْلِكُ لِنَفْسِي ضَرًّا وَلَا نَفْعًا إِلَّا مَا شَاءَ اللَّهُ لِكُلِّ أُمَّۃٍ أَجَلٌ إِذَا جَاءَ أَجَلُهُمْ فَلَا يَسْتَأْخِرُونَ سَاعَۃً وَلَا يَسْتَقْدِمُونَ‘‘ — کہدو — میں — اپنے لیے — نقصان — اور — فائدہ — دونوں کا — اختیار نہیں رکھتا — مگر — جتنا — اللہ — چاہے — ہر امت — کا — ایک وقت معین — ہے — جب — ان کا وقت — آ جاتا ہے — تو — نہ — ایک گھڑی — تاخیر ہوتی ہے — نہ — تقدیم ہوتی ہے — یعنی نبیؐ — خود بھی — بغیر اللہ — کے — کچھ نہیں کر سکتے؛ ہر امت — کا وقت — معین — ہے؛ نہ — تاخیر نہ تقدیم۔
۳۔ عملی سبق: اللہ — ہر چیز کا — مالک ہے؛ اس پر بھروسہ کرو۔"""
),
1414: (
"کہدو — بتاؤ — اگر — اس — کا عذاب — رات کو یا دن کو — تمہارے پاس آ جائے — تو — مجرم — اس میں سے — جلد باز — کیا چاہتے ہیں",
"""۱۔ عذاب — کسی بھی وقت — آ سکتا ہے — رات یا دن۔
۲۔ ’’قُلْ أَرَأَيْتُمْ إِنْ أَتَاكُمْ عَذَابُهُ بَيَاتًا أَوْ نَهَارًا مَّاذَا يَسْتَعْجِلُ مِنْهُ الْمُجْرِمُونَ‘‘ — کہدو — بتاؤ — اگر — اس — کا عذاب — رات کو یا دن کو — تمہارے پاس آ جائے — تو — مجرم — اس میں سے — جلد باز — کیا چاہتے ہیں — یعنی اگر عذاب — رات یا دن — کسی بھی وقت — آئے — تو مجرم — کیا چاہتے ہیں۔
۳۔ عملی سبق: عذاب — کسی بھی وقت — آ سکتا ہے؛ توبہ — کرو۔"""
),
}
